pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound domain: deposit and withdraw amounts must be positive and non-overflowing
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Deploy an adversarial helper that accepts ETH but does nothing
        // This is needed because the property concerns Owner's balance change,
        // and the fuzzer's raw address is an EOA that always accepts, but we need
        // an Owner that is a contract to expose the bug: the buggy mutant sends
        // ETH to msg.sender (Owner), but if Owner is a contract with a non-
        // reverting receive, the bug fails to credit Owner, while the reference
        // correctly transfers to Owner (payable(Owner)). So we must deploy a
        // contract that can receive ETH and measure its balance change.
        Acceptor acceptor = new Acceptor();
        address owner = address(acceptor);

        // Fund the contract C
        vm.deal(address(this), depositAmount);
        c.Command{value: depositAmount}(address(c), "");
        require(address(c).balance == depositAmount, "setup deposit");

        // Record pre-balances
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Owner calls withdraw (withdraw takes no parameters, so fuzzed amounts
        // are used only to set up a variable balance before the call).
        vm.prank(owner);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("withdraw()"));

        // After a successful withdraw, the Owner's balance must increase
        // by exactly the contract's balance before the call.
        if (ok) {
            assertTrue(owner.balance == ownerBalanceBefore + contractBalanceBefore);
        }
    }
}

