pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address adr, uint256 amount) public {
        // Constrain amount to cover large values where overflow can happen, but keep wide
        // Also ensure adr is not the contract itself to avoid selfdestruct-like edge cases
        vm.assume(adr != address(c));
        vm.assume(amount > 0);

        // Fund the contract with some Ether to be able to make balance >= msg.value scenarios
        uint256 initialFunding = 1 ether;
        vm.deal(address(this), initialFunding);
        vm.prank(address(this));
        (bool success,) = address(c).call{value: initialFunding}("");
        require(success, "funding failed");

        // Record pre-call contract balance
        uint256 preBalance = address(c).balance;

        // Execute multiplicate with fuzzed address and amount
        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.multiplicate{value: amount}(adr);

        // Read post-call contract balance
        uint256 postBalance = address(c).balance;

        // General invariant: if a transfer was triggered (msg.value >= preBalance),
        // the sum of postBalance + amount must equal preBalance (conservation of Ether).
        // The mutant can violate this when amount + preBalance overflows, causing a transfer
        // but postBalance + amount != preBalance.
        if (amount >= preBalance) {
            assertEq(postBalance + amount, preBalance, "invariant violated: conservation of Ether broken");
        }
    }
}

